package com.biocircular.compostaje.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="compost") public class Compost { @Id @GeneratedValue private UUID id; @OneToOne @JoinColumn(name="lote_id") private Lote lote; @Column(name="fecha_produccion") private LocalDate fechaProduccion; @Column(name="cantidad_kg") private BigDecimal cantidadKg; @Column(name="apto_entrega") private boolean aptoEntrega; public UUID getId(){return id;} public Lote getLote(){return lote;} public LocalDate getFechaProduccion(){return fechaProduccion;} public BigDecimal getCantidadKg(){return cantidadKg;} public boolean isAptoEntrega(){return aptoEntrega;} public void crear(Lote l,LocalDate f,BigDecimal c,boolean apto){lote=l;fechaProduccion=f;cantidadKg=c;aptoEntrega=apto;} }
